-- Contract v1.3: client reason DROWSINESS_SUSPECTED (eyes closed while seated → DISTRACTION_SUSPECTED).
-- The V1 inline CHECKs got PostgreSQL's default names <table>_<column>_check.
ALTER TABLE monitoring_events DROP CONSTRAINT monitoring_events_reason_check;
ALTER TABLE monitoring_events ADD CONSTRAINT monitoring_events_reason_check CHECK (reason IN ('SESSION_STARTED','SEATED_CONFIRMED','FOCUS_RESUMED','PRESENCE_LOST','PHONE_SUSPECTED','DROWSINESS_SUSPECTED','LOW_CONFIDENCE','CAMERA_STOPPED','CAMERA_PERMISSION_DENIED','INFERENCE_STALLED','MODEL_ERROR','MONITORING_PAUSED','BREAK_STARTED','BREAK_ENDED','RECONNECTED','HEARTBEAT_TIMEOUT','SESSION_ENDED','SESSION_REPLACED'));
ALTER TABLE activity_intervals DROP CONSTRAINT activity_intervals_reason_check;
ALTER TABLE activity_intervals ADD CONSTRAINT activity_intervals_reason_check CHECK (reason IN ('SESSION_STARTED','SEATED_CONFIRMED','FOCUS_RESUMED','PRESENCE_LOST','PHONE_SUSPECTED','DROWSINESS_SUSPECTED','LOW_CONFIDENCE','CAMERA_STOPPED','CAMERA_PERMISSION_DENIED','INFERENCE_STALLED','MODEL_ERROR','MONITORING_PAUSED','BREAK_STARTED','BREAK_ENDED','RECONNECTED','HEARTBEAT_TIMEOUT','SESSION_ENDED','SESSION_REPLACED'));
